/* ============================================================
   Inkwell Jazz Festival — Reference Site
   handmade_illustrated · storytelling_scroll
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght,SOFT@9..144,400;9..144,500;9..144,700;9..144,800;9..144,900&family=Nunito:wght@400;500;600;700;800&family=Caveat:wght@400;500;600;700&display=swap');

:root {
  --parchment: #F5EDDA;
  --ink: #2C2118;
  --coral: #E8614A;
  --olive: #6B7A3A;
  --mustard: #D4A72C;
  --sky: #7BBFD4;
  --linen: #C8BEA8;
  --plum: #5C3460;

  --coral-deep: #c64f3a;
  --plum-deep: #482550;

  --font-h: "Fraunces", "Times New Roman", serif;
  --font-b: "Nunito", system-ui, -apple-system, sans-serif;
  --font-a: "Caveat", "Brush Script MT", cursive;

  --ease-soft: cubic-bezier(0.22, 0.61, 0.36, 1);
  --ease-pen: cubic-bezier(0.34, 1.18, 0.64, 1);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-b);
  background: var(--parchment);
  color: var(--ink);
  font-size: 17px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
  position: relative;
}

/* Paper grain texture (subtle dotted noise via radial gradients) */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: 0.08;
  background-image:
    radial-gradient(circle at 12% 18%, var(--ink) 0.4px, transparent 1.1px),
    radial-gradient(circle at 78% 32%, var(--ink) 0.4px, transparent 1.1px),
    radial-gradient(circle at 42% 67%, var(--ink) 0.4px, transparent 1.1px),
    radial-gradient(circle at 88% 88%, var(--ink) 0.4px, transparent 1.1px);
  background-size: 5px 5px, 7px 7px, 6px 6px, 9px 9px;
  animation: grain-drift 8s linear infinite;
}

@keyframes grain-drift {
  0%   { transform: translate(0, 0); }
  25%  { transform: translate(2px, -1px); }
  50%  { transform: translate(-1px, 2px); }
  75%  { transform: translate(1px, 1px); }
  100% { transform: translate(0, 0); }
}

a { color: inherit; text-decoration: none; }
img, svg { display: block; max-width: 100%; }

/* ============================================================
   NAVIGATION
   ============================================================ */
.site-nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(245, 237, 218, 0.92);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border-bottom: 1px dashed var(--linen);
}

.nav-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 18px 32px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-h);
  font-weight: 900;
  font-size: 22px;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.brand-mark {
  width: 36px; height: 36px;
  display: inline-block;
  flex-shrink: 0;
}

.brand-mark .ink-blot {
  fill: var(--coral);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-b);
  font-weight: 600;
  font-size: 15px;
  color: var(--ink);
  position: relative;
  padding: 6px 0;
  transition: color 0.18s ease;
}

.nav-links a::after {
  content: "";
  position: absolute;
  left: 0; bottom: 2px;
  height: 2px;
  width: 0;
  background: var(--coral);
  transition: width 0.28s var(--ease-soft);
  border-radius: 2px;
}

.nav-links a:hover::after,
.nav-links a.is-current::after { width: 100%; }

.nav-links a.is-current { color: var(--coral); }

.nav-cta {
  background: var(--coral);
  color: var(--parchment) !important;
  padding: 10px 20px !important;
  border-radius: 7px 9px 7px 8px;
  font-family: var(--font-b);
  font-weight: 700;
  font-size: 14px !important;
  transition: transform 0.2s var(--ease-soft), background 0.2s ease;
}

.nav-cta::after { display: none; }

.nav-cta:hover {
  transform: translateY(-2px);
  background: var(--coral-deep);
}

/* ============================================================
   GLOBAL TYPE
   ============================================================ */
.eyebrow {
  font-family: var(--font-a);
  font-size: 14px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--coral);
  font-weight: 600;
  display: inline-block;
  margin-bottom: 12px;
}

h1, h2, h3, h4 {
  font-family: var(--font-h);
  color: var(--ink);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.01em;
}

p { font-family: var(--font-b); }

.section-wrap {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 32px;
  position: relative;
  z-index: 2;
}

/* ============================================================
   WOBBLY DIVIDER (used between sections)
   ============================================================ */
.divider {
  width: 100%;
  display: block;
  height: 28px;
  position: relative;
}

.divider svg {
  width: 100%;
  height: 100%;
  display: block;
}

/* ============================================================
   BUTTONS / CTAs
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  font-family: var(--font-b);
  font-weight: 700;
  font-size: 16px;
  padding: 14px 30px;
  border-radius: 7px 10px 6px 9px;
  background: var(--coral);
  color: var(--parchment);
  border: none;
  cursor: pointer;
  position: relative;
  transition: transform 0.2s var(--ease-soft), background 0.2s ease, box-shadow 0.2s ease;
  text-decoration: none;
  box-shadow: 0 2px 0 rgba(44, 33, 24, 0.18);
}

.btn::before {
  content: "";
  position: absolute;
  inset: -4px;
  border: 1.5px dashed var(--linen);
  border-radius: 9px 12px 8px 11px;
  pointer-events: none;
  opacity: 0.75;
  transition: border-color 0.2s ease, opacity 0.2s ease;
}

.btn:hover {
  transform: translateY(-3px);
  background: var(--coral-deep);
  box-shadow: 0 6px 14px rgba(44, 33, 24, 0.18);
}

.btn:focus-visible {
  outline: none;
}
.btn:focus-visible::before {
  border-color: var(--mustard);
  border-width: 2px;
  opacity: 1;
}

.btn--secondary {
  background: var(--ink);
  color: var(--parchment);
}
.btn--secondary:hover { background: #1d1610; }

.btn--ghost {
  background: transparent;
  color: var(--parchment);
  border: 1.5px solid var(--parchment);
  box-shadow: none;
}
.btn--ghost::before { display: none; }
.btn--ghost:hover {
  background: rgba(245, 237, 218, 0.08);
  color: var(--mustard);
  border-color: var(--mustard);
  border-width: 2px;
}

.btn--pill {
  border-radius: 999px;
  padding: 16px 38px;
}

.text-link {
  font-family: var(--font-b);
  font-weight: 700;
  font-size: 16px;
  color: var(--coral);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  position: relative;
  padding-bottom: 4px;
}

.text-link::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0;
  height: 2px; width: 0;
  background: var(--coral);
  transition: width 0.32s var(--ease-soft);
  border-radius: 2px;
}
.text-link:hover::after { width: 100%; }
.text-link .arrow { transition: transform 0.25s var(--ease-soft); }
.text-link:hover .arrow { transform: translateX(4px); }

/* ============================================================
   REVEAL SYSTEM (driven by JS)
   ============================================================ */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.8s var(--ease-soft), transform 0.8s var(--ease-soft);
  will-change: opacity, transform;
}
.reveal.is-in {
  opacity: 1;
  transform: translateY(0);
}
.reveal.from-left { transform: translateX(-30px); }
.reveal.from-left.is-in { transform: translateX(0); }
.reveal.from-right { transform: translateX(30px); }
.reveal.from-right.is-in { transform: translateX(0); }
.reveal.scale-in { transform: scale(0.96); }
.reveal.scale-in.is-in { transform: scale(1); }

.stagger > * {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.7s var(--ease-soft), transform 0.7s var(--ease-soft);
}
.stagger.is-in > * { opacity: 1; transform: translateY(0); }
.stagger.is-in > *:nth-child(1) { transition-delay: 0.05s; }
.stagger.is-in > *:nth-child(2) { transition-delay: 0.15s; }
.stagger.is-in > *:nth-child(3) { transition-delay: 0.25s; }
.stagger.is-in > *:nth-child(4) { transition-delay: 0.35s; }
.stagger.is-in > *:nth-child(5) { transition-delay: 0.45s; }
.stagger.is-in > *:nth-child(6) { transition-delay: 0.55s; }

/* ============================================================
   HERO (HOME)
   ============================================================ */
.hero {
  min-height: 100vh;
  position: relative;
  padding: 90px 0 60px;
  overflow: hidden;
}

.hero-frame {
  position: absolute;
  inset: 24px;
  pointer-events: none;
  z-index: 1;
}
.hero-frame svg { width: 100%; height: 100%; }

.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 24px 64px;
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 20px;
  align-items: center;
  min-height: calc(100vh - 220px);
}

.hero-text {
  max-width: 720px;
}

.hero-eyebrow {
  display: inline-block;
  position: relative;
  padding-bottom: 10px;
  color: var(--ink);
  font-size: 14px;
  letter-spacing: 0.06em;
  text-transform: none;
  font-family: var(--font-a);
  font-weight: 600;
}
.hero-eyebrow::after {
  content: "";
  position: absolute;
  left: 0; bottom: 0;
  width: 130px; height: 4px;
  background: var(--mustard);
  border-radius: 60% 40% 50% 50%;
  transform: rotate(-1.2deg);
}

.hero-h1 {
  font-size: clamp(48px, 8vw, 96px);
  font-weight: 900;
  line-height: 0.98;
  margin: 18px 0 22px;
  letter-spacing: -0.02em;
}

.hero-h1 .word {
  display: inline-block;
  opacity: 0;
  transform: translateY(28px);
  animation: word-rise 0.7s var(--ease-pen) forwards;
}
.hero-h1 .word:nth-child(1) { animation-delay: 0.5s; }
.hero-h1 .word:nth-child(2) { animation-delay: 0.6s; }
.hero-h1 .word:nth-child(3) { animation-delay: 0.7s; }
.hero-h1 .word:nth-child(4) { animation-delay: 0.8s; }
.hero-h1 .word:nth-child(5) { animation-delay: 0.9s; }

@keyframes word-rise {
  to { opacity: 1; transform: translateY(0); }
}

.ink-splash-wrap {
  position: relative;
  display: inline-block;
  z-index: 1;
}
.ink-splash-wrap > .word-text {
  position: relative;
  z-index: 2;
}
.ink-splash {
  position: absolute;
  inset: -24% -16%;
  z-index: 1;
  pointer-events: none;
  transform: scale(0);
  transform-origin: center;
  animation: splash-grow 1.1s var(--ease-pen) 0.8s forwards;
}
.ink-splash svg { width: 100%; height: 100%; }

@keyframes splash-grow {
  0%   { transform: scale(0) rotate(-4deg); opacity: 0; }
  50%  { opacity: 0.95; }
  100% { transform: scale(1) rotate(0); opacity: 1; }
}

.hero-sub {
  font-family: var(--font-h);
  font-weight: 400;
  font-style: italic;
  font-size: clamp(20px, 2.2vw, 26px);
  line-height: 1.4;
  max-width: 540px;
  color: var(--ink);
  opacity: 0;
  transform: translateY(14px);
  animation: rise-soft 0.7s var(--ease-soft) 1.55s forwards;
}

@keyframes rise-soft {
  to { opacity: 1; transform: translateY(0); }
}

.hero-ctas {
  display: flex;
  gap: 16px;
  margin-top: 32px;
  flex-wrap: wrap;
  opacity: 0;
  animation: rise-soft 0.6s var(--ease-soft) 1.85s forwards;
}

.hero-illustration {
  position: relative;
  width: 100%;
  height: 480px;
  opacity: 0;
  animation: trumpet-arrive 0.9s var(--ease-soft) 1.2s forwards;
}

@keyframes trumpet-arrive {
  from { opacity: 0; transform: translate(40px, 40px); }
  to   { opacity: 1; transform: translate(0, 0); }
}

.trumpet-floater {
  width: 100%;
  height: 100%;
  animation: float-y 4.5s ease-in-out infinite;
}

@keyframes float-y {
  0%, 100% { transform: translateY(0); }
  50%      { transform: translateY(-8px); }
}

/* ============================================================
   STATS MARQUEE (HOME)
   ============================================================ */
.stats-section {
  background: var(--sky);
  position: relative;
  padding: 56px 0 64px;
  overflow: hidden;
}

.stats-head {
  text-align: center;
  margin-bottom: 28px;
}
.stats-eyebrow {
  font-family: var(--font-a);
  font-size: 14px;
  color: var(--ink);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  position: relative;
  padding-bottom: 14px;
  display: inline-block;
}
.stats-eyebrow::before,
.stats-eyebrow::after {
  content: "";
  position: absolute;
  left: 0; right: 0;
  height: 2px;
  background: var(--mustard);
  border-radius: 50%;
  bottom: 4px;
}
.stats-eyebrow::after { bottom: 0; left: 8px; right: 8px; height: 1.5px; }

.stats-caption {
  font-family: var(--font-a);
  font-size: 18px;
  color: var(--ink);
  margin-top: 8px;
}

.marquee {
  position: relative;
  overflow: hidden;
  padding: 24px 0;
}
.marquee-track {
  display: flex;
  align-items: center;
  gap: 80px;
  width: max-content;
  animation: marquee 38s linear infinite;
}
.marquee:hover .marquee-track { animation-play-state: paused; }

.stat-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 0 18px;
  transition: transform 0.2s ease;
}
.stat-item:hover { transform: translateY(-2px); }
.stat-num {
  font-family: var(--font-h);
  font-size: clamp(56px, 7vw, 80px);
  font-weight: 800;
  color: var(--mustard);
  line-height: 1;
  letter-spacing: -0.02em;
  transition: transform 0.2s var(--ease-soft), filter 0.2s ease;
}
.stat-item:hover .stat-num { transform: scale(1.04); filter: brightness(1.08); }

.stat-desc {
  font-family: var(--font-b);
  font-size: 15px;
  color: var(--ink);
  max-width: 220px;
  text-align: center;
}

.marquee-sep {
  width: 3px;
  height: 56px;
  background: var(--linen);
  border-radius: 2px;
  transform: rotate(-4deg);
}

@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ============================================================
   STORY BLOCK (HOME)
   ============================================================ */
.story {
  padding: 100px 0;
  position: relative;
  background: var(--parchment);
}

.story-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr;
  gap: 80px;
  align-items: start;
}

.story-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--font-a);
  font-size: 14px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink);
}
.story-eyebrow::before {
  content: "•";
  color: var(--coral);
  font-size: 22px;
  line-height: 1;
}

.story-h2 {
  font-size: clamp(34px, 4.5vw, 48px);
  margin: 14px 0 20px;
  font-weight: 800;
}
.story-h2 .underline-word {
  position: relative;
  display: inline-block;
}
.story-h2 .underline-word::after {
  content: "";
  position: absolute;
  left: -4px; right: -4px;
  bottom: -2px;
  height: 6px;
  background: var(--mustard);
  border-radius: 60% 40% 60% 40%;
  z-index: -1;
  opacity: 0.85;
}

.story-sub {
  font-family: var(--font-h);
  font-size: 20px;
  font-weight: 400;
  line-height: 1.5;
  margin-bottom: 24px;
  color: var(--ink);
}

.story-body p {
  font-size: 17px;
  line-height: 1.78;
  max-width: 56ch;
  margin-bottom: 18px;
}

.pullquote {
  position: sticky;
  top: 100px;
  padding-left: 12px;
}
.pullquote .qmark {
  font-family: var(--font-h);
  font-size: 160px;
  font-weight: 900;
  color: var(--coral);
  line-height: 0.8;
  display: block;
  margin-bottom: 0;
}
.pullquote .quote-text {
  font-family: var(--font-a);
  font-size: 22px;
  color: var(--ink);
  line-height: 1.4;
  margin-top: 8px;
}
.pullquote .squiggle {
  margin-top: 14px;
  display: block;
}

/* ============================================================
   CTA PANELS (full-bleed Velvet Plum)
   ============================================================ */
.cta-panel {
  background: var(--plum);
  color: var(--parchment);
  padding: 110px 32px;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-panel::before {
  content: "";
  position: absolute;
  top: 18px; left: 0; right: 0;
  height: 3px;
  background: var(--mustard);
  border-radius: 50% 60% 40% 50% / 50%;
  opacity: 0.9;
}

.cta-seal {
  width: 28px;
  height: 28px;
  margin: 0 auto 30px;
  position: relative;
  z-index: 2;
}

.cta-eyebrow {
  font-family: var(--font-a);
  color: var(--mustard);
  font-size: 15px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  position: relative;
  display: inline-block;
  padding: 0 28px;
}
.cta-eyebrow::before,
.cta-eyebrow::after {
  content: "";
  position: absolute;
  top: 50%; width: 18px; height: 2px;
  background: var(--mustard);
  opacity: 0.8;
}
.cta-eyebrow::before { left: 0; }
.cta-eyebrow::after { right: 0; }

.cta-h2 {
  font-family: var(--font-h);
  font-size: clamp(34px, 6vw, 56px);
  font-weight: 900;
  color: var(--parchment);
  margin: 22px 0 18px;
  line-height: 1.05;
}
.cta-h2 .underline-word::after { background: var(--mustard); }

.cta-sub {
  font-family: var(--font-h);
  font-weight: 400;
  font-size: 20px;
  color: rgba(245, 237, 218, 0.82);
  max-width: 520px;
  margin: 0 auto 40px;
  line-height: 1.5;
}

.pulse-cta { animation: btn-pulse 3s ease-in-out infinite; }
@keyframes btn-pulse {
  0%, 100% { transform: scale(1); box-shadow: 0 2px 0 rgba(44, 33, 24, 0.2); }
  50%      { transform: scale(1.025); box-shadow: 0 0 0 6px rgba(232, 97, 74, 0.18), 0 2px 0 rgba(44, 33, 24, 0.2); }
}

.cta-notes {
  position: absolute;
  bottom: 8px; left: 0; right: 0;
  height: 50px;
  opacity: 0.4;
  pointer-events: none;
}

/* ============================================================
   PAGE HEADER (Experience / Lineup / Map / Tickets)
   ============================================================ */
.page-header {
  padding: 130px 0 90px;
  background: var(--parchment);
  position: relative;
  overflow: hidden;
}

.page-header .section-wrap { max-width: 1100px; }

.page-h1 {
  font-size: clamp(40px, 6.6vw, 80px);
  line-height: 1.04;
  font-weight: 800;
  margin: 14px 0 22px;
  max-width: 16ch;
}

.page-sub {
  font-family: var(--font-b);
  font-size: 18px;
  line-height: 1.7;
  max-width: 56ch;
  color: rgba(44, 33, 24, 0.82);
}

.page-header .header-line {
  margin-top: 40px;
  max-width: 360px;
}

.header-line svg .draw-line {
  stroke-dasharray: 340;
  stroke-dashoffset: 340;
  animation: draw 1.4s var(--ease-soft) 0.9s forwards;
}

@keyframes draw {
  to { stroke-dashoffset: 0; }
}

.page-h1 .word-anim {
  display: inline-block;
  opacity: 0;
  transform: translateY(14px);
  animation: word-rise 0.6s var(--ease-pen) forwards;
}

/* ============================================================
   EXPERIENCE - FEATURE GRID
   ============================================================ */
.feature-section {
  background: var(--sky);
  padding: 90px 0;
  position: relative;
}

.feature-head { margin-bottom: 40px; }
.feature-head h2 { font-size: clamp(32px, 4vw, 52px); margin-top: 8px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.feature-card {
  background: var(--parchment);
  padding: 28px;
  position: relative;
  border-radius: 10px 14px 11px 13px;
  border: 1.5px solid var(--linen);
  transition: transform 0.22s var(--ease-soft), border-color 0.22s, background 0.22s, box-shadow 0.22s;
  box-shadow: 2px 4px 0 rgba(44, 33, 24, 0.04);
}
.feature-card:nth-child(2),
.feature-card:nth-child(5) { margin-top: 18px; }

.feature-card:hover {
  transform: translateY(-5px);
  border-color: var(--coral);
  background: #faecdc;
  box-shadow: 4px 10px 18px rgba(44, 33, 24, 0.1);
}
.feature-card:hover .feature-icon { transform: scale(1.08); }

.feature-icon {
  width: 44px;
  height: 44px;
  color: var(--olive);
  margin-bottom: 18px;
  transition: transform 0.25s var(--ease-pen);
}

.feature-card h3 {
  font-family: var(--font-h);
  font-size: 22px;
  font-weight: 700;
  margin-bottom: 10px;
}
.feature-card p {
  font-size: 15.5px;
  line-height: 1.65;
  color: rgba(44, 33, 24, 0.85);
}

.feature-cta { text-align: center; margin-top: 48px; }

/* ============================================================
   EXPERIENCE - STORY BLOCK (Velvet Plum, ghost text)
   ============================================================ */
.dark-story {
  background: var(--plum);
  color: var(--parchment);
  padding: 120px 0;
  position: relative;
  overflow: hidden;
}

.ghost-text {
  position: absolute;
  right: -40px;
  top: 50%;
  transform: translate(0, -45%);
  font-family: var(--font-h);
  font-weight: 900;
  font-size: clamp(60px, 12vw, 140px);
  color: var(--parchment);
  opacity: 0;
  line-height: 1;
  letter-spacing: -0.02em;
  pointer-events: none;
  white-space: nowrap;
  z-index: 0;
  transition: opacity 2s ease;
  will-change: transform, opacity;
}
.dark-story.is-visible .ghost-text { opacity: 0.12; }

.dark-story .section-wrap {
  max-width: 1240px;
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 60px;
  align-items: center;
}

.dark-story-content {
  max-width: 580px;
  position: relative;
  z-index: 2;
}
.dark-story .eyebrow { color: var(--mustard); }
.dark-story h2 {
  font-size: clamp(36px, 4.5vw, 56px);
  color: var(--parchment);
  margin-bottom: 24px;
  line-height: 1.05;
}
.dark-story p {
  font-size: 18px;
  line-height: 1.8;
  color: rgba(245, 237, 218, 0.9);
  max-width: 58ch;
}

.smoke-wisp {
  position: absolute;
  top: 60px;
  right: 80px;
  width: 110px;
  opacity: 0.15;
  z-index: 1;
  animation: smoke-breathe 4s ease-in-out infinite;
}

@keyframes smoke-breathe {
  0%, 100% { transform: scale(1) rotate(2deg); opacity: 0.15; }
  50%      { transform: scale(1.06) rotate(-1deg); opacity: 0.22; }
}

/* ============================================================
   LINEUP - HEADLINER CARDS
   ============================================================ */
.lineup-header {
  min-height: 100vh;
  background: var(--ink);
  color: var(--parchment);
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: flex-end;
}

.poster-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
  opacity: 0.5;
  filter: saturate(0.7);
}
.poster-bg svg { width: 100%; height: 100%; }

.parchment-overlay {
  position: absolute;
  inset: 0;
  background: var(--parchment);
  mix-blend-mode: multiply;
  opacity: 0.25;
  z-index: 1;
  pointer-events: none;
}

.lineup-header .section-wrap {
  position: relative;
  z-index: 2;
  max-width: 1240px;
  padding: 0 64px 48px;
}

.bill-cascade {
  display: flex;
  flex-direction: column;
  line-height: 0.92;
  margin-bottom: 28px;
}
.bill-line {
  font-family: var(--font-h);
  font-weight: 900;
  display: inline-block;
  opacity: 0;
  transform: translateY(-32px);
  animation: bill-drop 0.7s var(--ease-pen) forwards;
}
.bill-line--lg {
  font-size: clamp(72px, 12vw, 120px);
  color: var(--coral);
  margin-left: -6px;
  animation-delay: 0.4s;
}
.bill-line--md {
  font-size: clamp(48px, 8vw, 78px);
  color: var(--parchment);
  font-weight: 700;
  animation-delay: 0.65s;
}
.bill-line--sm {
  font-size: clamp(38px, 6vw, 60px);
  color: var(--mustard);
  font-weight: 700;
  animation-delay: 0.85s;
}

@keyframes bill-drop {
  0%   { opacity: 0; transform: translateY(-32px); }
  60%  { opacity: 1; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0); }
}

.lineup-header .eyebrow {
  color: var(--mustard);
  opacity: 0;
  animation: rise-soft 0.5s ease 1.05s forwards;
}
.lineup-header .page-sub {
  color: rgba(245, 237, 218, 0.86);
  max-width: 480px;
  opacity: 0;
  animation: rise-soft 0.5s ease 1.25s forwards;
}

.headliners {
  background: var(--parchment);
  padding: 90px 0;
}

.headliners-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 36px;
}

.headliner-card {
  background: var(--plum);
  color: var(--parchment);
  padding: 30px 28px;
  border-radius: 9px 13px 10px 12px;
  border: 2px solid var(--linen);
  transition: transform 0.25s var(--ease-soft), border-color 0.25s, box-shadow 0.25s;
  position: relative;
}
.headliner-card:nth-child(2) { margin-top: 24px; }
.headliner-card:nth-child(3) { margin-top: 12px; }

.headliner-card:hover {
  transform: translateY(-6px);
  border-color: var(--mustard);
  box-shadow: 4px 10px 22px rgba(44, 33, 24, 0.18);
}

.headliner-card h3 {
  font-family: var(--font-h);
  font-size: 28px;
  font-weight: 800;
  color: var(--mustard);
  line-height: 1.1;
  transition: color 0.2s ease;
  margin-bottom: 14px;
}
.headliner-card:hover h3 { color: var(--coral); }

.gig-badge {
  display: inline-block;
  background: var(--coral);
  color: var(--parchment);
  padding: 6px 14px;
  border-radius: 999px;
  font-family: var(--font-a);
  font-size: 13px;
  margin-bottom: 14px;
}

.headliner-card p {
  font-size: 15px;
  line-height: 1.65;
  color: rgba(245, 237, 218, 0.9);
}

/* ============================================================
   LINEUP - SUPPORTING ACTS
   ============================================================ */
.supporting {
  background: var(--sky);
  padding: 80px 0;
}

.supporting-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  column-gap: 56px;
  row-gap: 36px;
  margin-top: 36px;
}
.supporting-grid .col-right { margin-top: 48px; }

.act-entry {
  padding-bottom: 24px;
  position: relative;
}
.act-entry::after {
  content: "";
  position: absolute;
  left: 0; right: 30%;
  bottom: 0;
  height: 1px;
  background: var(--linen);
  border-radius: 50%;
  transform: rotate(-0.4deg);
}
.act-entry:last-child::after { display: none; }

.act-entry h3 {
  font-family: var(--font-h);
  font-size: 26px;
  font-weight: 700;
  color: var(--ink);
  margin-bottom: 8px;
  position: relative;
  display: inline-block;
}
.act-entry h3::after {
  content: "";
  position: absolute;
  left: 0; bottom: -2px;
  height: 2px; width: 0;
  background: var(--ink);
  transition: width 0.32s var(--ease-soft);
}
.act-entry:hover h3::after { width: 100%; }

.act-meta {
  font-family: var(--font-a);
  font-size: 14px;
  color: rgba(44, 33, 24, 0.7);
  margin-bottom: 6px;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
}

.stage-badge {
  display: inline-block;
  padding: 3px 12px;
  background: var(--olive);
  color: var(--parchment);
  border-radius: 999px;
  font-family: var(--font-a);
  font-size: 12px;
  letter-spacing: 0.03em;
  transition: filter 0.2s;
}
.act-entry:hover .stage-badge { filter: brightness(1.12); }

.act-entry p {
  font-size: 15.5px;
  line-height: 1.65;
  color: rgba(44, 33, 24, 0.85);
  max-width: 48ch;
}

/* ============================================================
   MAP PAGE
   ============================================================ */
.map-header { position: relative; }
.map-header .annotation {
  position: absolute;
  right: 6%;
  top: 50%;
  transform: translateY(-30%);
  font-family: var(--font-a);
  font-size: 30px;
  color: var(--olive);
  line-height: 1.2;
  max-width: 220px;
  animation: paper-breathe 6s ease-in-out infinite;
}
.map-header .annotation .arrow {
  display: inline-block;
  font-size: 36px;
  margin-right: 6px;
  transform: rotate(-12deg);
}

@keyframes paper-breathe {
  0%, 100% { transform: translateY(-30%) translateX(0); }
  50%      { transform: translateY(calc(-30% - 5px)) translateX(-2px); }
}

.map-header .page-h1 .squiggle-underline {
  position: relative;
}
.map-header .page-h1 .squiggle-underline::after {
  content: "";
  position: absolute;
  left: 0; right: 0; bottom: -10px;
  height: 8px;
  background: var(--coral);
  border-radius: 60% 40% 50% 50% / 50%;
  transform: rotate(-0.5deg);
  opacity: 0.8;
}

.map-block {
  background: var(--plum);
  color: var(--parchment);
  padding: 80px 0 100px;
  position: relative;
}
.map-block .eyebrow { color: var(--mustard); }
.map-block h2 {
  font-size: clamp(30px, 4.5vw, 52px);
  color: var(--mustard);
  margin: 10px 0 18px;
  line-height: 1.05;
}
.map-block .page-sub { color: var(--sky); max-width: 520px; }

.map-frame {
  margin-top: 48px;
  background: #f3e8cf;
  border-radius: 6px;
  padding: 24px;
  position: relative;
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.3);
  transition: filter 0.3s ease;
}
.map-frame:hover { filter: brightness(1.05); }

.map-svg {
  width: 100%;
  display: block;
  height: auto;
}

.compass-rose {
  position: absolute;
  right: -10px;
  bottom: -90px;
  width: 160px;
  height: 160px;
  z-index: 5;
}
.compass-rose .rose-rotate {
  width: 100%; height: 100%;
  animation: rose-rotate 60s linear infinite;
  transform-origin: 50% 50%;
}

@keyframes rose-rotate {
  to { transform: rotate(360deg); }
}

.map-zone-label {
  font-family: var(--font-a);
  font-size: 14px;
  fill: var(--ink);
  font-weight: 600;
}

/* Map label pop-in animation handled by JS */
.map-label-anim {
  transform-origin: center;
  transform-box: fill-box;
  opacity: 0;
  transform: scale(0.85);
  transition: opacity 0.3s ease, transform 0.3s var(--ease-pen);
}
.map-label-anim.is-shown {
  opacity: 1;
  transform: scale(1);
}

.locations {
  background: var(--parchment);
  padding: 130px 0 100px;
  position: relative;
}

.locations-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 26px;
  margin-top: 38px;
}

.location-card {
  background: var(--parchment);
  border: 1.5px solid var(--linen);
  padding: 24px;
  border-radius: 11px 14px 10px 13px;
  position: relative;
  transition: transform 0.22s var(--ease-soft), border-color 0.22s, box-shadow 0.22s;
  box-shadow: 1px 2px 0 rgba(44, 33, 24, 0.04);
}
.location-card:hover {
  transform: translateY(-4px);
  border-color: var(--coral);
  box-shadow: 4px 8px 18px rgba(44, 33, 24, 0.1);
}
.zone-badge {
  display: inline-block;
  padding: 3px 12px;
  border-radius: 999px;
  font-family: var(--font-a);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.03em;
  margin-bottom: 14px;
  transition: transform 0.2s ease;
}
.location-card:hover .zone-badge { transform: scale(1.05); }

.zone-entrance   { background: var(--coral);   color: var(--parchment); }
.zone-stages     { background: var(--plum);    color: var(--parchment); }
.zone-food       { background: var(--mustard); color: var(--ink); }
.zone-activities { background: var(--olive);   color: var(--parchment); }
.zone-facilities { background: var(--sky);     color: var(--ink); }

.location-card h3 {
  font-family: var(--font-h);
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
  line-height: 1.2;
}
.location-card p {
  font-size: 15px;
  line-height: 1.65;
  color: rgba(44, 33, 24, 0.82);
}

/* ============================================================
   FAQ
   ============================================================ */
.faq-section {
  padding: 90px 0 110px;
  position: relative;
  background: linear-gradient(0deg, rgba(123, 191, 212, 0.28), rgba(123, 191, 212, 0.28)), var(--parchment);
}

.faq-head h2 { font-size: clamp(28px, 4vw, 40px); }
.faq-head .header-line { max-width: 130px; margin-top: 12px; }

.faq-list {
  max-width: 720px;
  margin: 40px 0 0;
}

.faq-item {
  border-top: 1.5px solid var(--linen);
  padding: 4px 0;
}
.faq-item:last-child {
  border-bottom: 1.5px solid var(--linen);
}

.faq-trigger {
  background: none;
  border: none;
  cursor: pointer;
  width: 100%;
  text-align: left;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  font-family: var(--font-h);
  font-size: 20px;
  font-weight: 700;
  color: var(--ink);
  padding: 22px 0;
  transition: color 0.18s;
}
.faq-trigger:hover { color: var(--coral); }
.faq-trigger:focus-visible {
  outline: 2px dashed var(--mustard);
  outline-offset: 4px;
}

.faq-toggle {
  width: 22px; height: 22px;
  color: var(--olive);
  transition: transform 0.28s var(--ease-soft);
  flex-shrink: 0;
}
.faq-item.is-open .faq-toggle { transform: rotate(45deg); }

.faq-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.32s var(--ease-soft);
}
.faq-body-inner {
  padding: 0 0 22px 16px;
  font-size: 16px;
  line-height: 1.75;
  color: rgba(44, 33, 24, 0.85);
  max-width: 60ch;
}

.faq-cta {
  margin-top: 56px;
  text-align: center;
}
.faq-cta .ann {
  display: block;
  font-family: var(--font-a);
  font-size: 17px;
  color: var(--olive);
  margin-bottom: 14px;
}

/* ============================================================
   TICKETS - PRICING
   ============================================================ */
.pricing-section {
  background: var(--parchment);
  padding: 100px 0 110px;
  position: relative;
  overflow: hidden;
}
.pricing-head { max-width: 720px; margin-bottom: 60px; }
.pricing-head h2 { font-size: clamp(30px, 4vw, 44px); margin: 8px 0 16px; }
.pricing-head p  {
  font-size: 15px;
  color: rgba(44, 33, 24, 0.7);
  max-width: 56ch;
  line-height: 1.6;
}

.pricing-wristband {
  position: absolute;
  right: 40px;
  top: 130px;
  width: 380px;
  z-index: 4;
  transform: rotate(20deg) translateX(20px);
  opacity: 0;
  pointer-events: none;
  filter: drop-shadow(0 8px 16px rgba(44, 33, 24, 0.18));
  transition: transform 1s var(--ease-pen), opacity 0.9s var(--ease-soft);
}
.pricing-section.is-visible .pricing-wristband {
  transform: rotate(12deg) translateX(0);
  opacity: 1;
}

.pricing-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  position: relative;
  z-index: 2;
}

.tier-card {
  background: var(--parchment);
  border: 2px solid var(--linen);
  padding: 32px 28px 28px;
  border-radius: 10px 14px 11px 13px;
  position: relative;
  transition: transform 0.25s var(--ease-soft), border-color 0.25s, box-shadow 0.25s;
}
.tier-card:hover {
  transform: translateY(-4px);
  border-color: var(--coral);
  box-shadow: 4px 10px 24px rgba(44, 33, 24, 0.1);
}

.tier-card h3 {
  font-family: var(--font-h);
  font-size: 24px;
  font-weight: 600;
  margin-bottom: 6px;
}

.tier-price {
  font-family: var(--font-h);
  font-size: 42px;
  font-weight: 900;
  color: var(--ink);
  letter-spacing: -0.02em;
  margin: 10px 0 14px;
  display: block;
}

.tier-card p {
  font-size: 15px;
  line-height: 1.7;
  color: rgba(44, 33, 24, 0.84);
  margin-bottom: 8px;
}

.tier-features {
  list-style: none;
  margin: 14px 0 22px;
  padding-left: 0;
}
.tier-features li {
  position: relative;
  padding-left: 22px;
  font-size: 15px;
  line-height: 1.7;
}
.tier-features li::before {
  content: "•";
  position: absolute;
  left: 4px;
  top: -2px;
  color: var(--coral);
  font-size: 22px;
  font-weight: 900;
}

.tier-avail {
  display: inline-block;
  padding: 3px 11px;
  border-radius: 999px;
  font-family: var(--font-a);
  font-size: 13px;
  letter-spacing: 0.03em;
  margin-bottom: 10px;
}
.avail-available { background: rgba(107, 122, 58, 0.18); color: var(--olive); }
.avail-limited   { background: rgba(212, 167, 44, 0.22); color: #a07f17; animation: scarcity-pulse 3s ease-in-out infinite; }
.avail-very      { background: rgba(232, 97, 74, 0.18); color: var(--coral-deep); animation: scarcity-pulse 3s ease-in-out infinite; }

@keyframes scarcity-pulse {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.7; }
}

.tier-card .btn { width: 100%; }

.tier-card--recommended {
  border-color: var(--mustard);
  border-width: 3px;
}
.tier-card--recommended::before {
  content: "Best Value";
  position: absolute;
  top: -16px; left: -10px;
  font-family: var(--font-a);
  font-size: 16px;
  color: var(--coral);
  background: var(--mustard);
  padding: 5px 18px;
  border-radius: 6px;
  transform: rotate(-6deg);
  font-weight: 700;
  box-shadow: 2px 3px 0 rgba(44, 33, 24, 0.15);
  z-index: 3;
}

.tier-card--vip {
  position: relative;
}
.tier-card--vip::after {
  content: "";
  position: absolute;
  left: 0; top: 0; bottom: 0;
  width: 5px;
  background: var(--plum);
  border-radius: 4px 0 0 4px;
}
.tier-card--vip h3 { color: var(--plum); }

/* ============================================================
   TICKETS - TESTIMONIALS
   ============================================================ */
.testimonials {
  background: var(--sky);
  padding: 100px 0;
  text-align: left;
}

.testimonials-head { text-align: center; margin-bottom: 56px; }
.testimonials-head h2 { font-size: clamp(28px, 4vw, 44px); }

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  align-items: start;
}
.testimonials-grid .t-card:nth-child(2) { margin-top: 32px; }
.testimonials-grid .t-card:nth-child(3) { margin-top: -16px; }

.t-card {
  background: var(--parchment);
  padding: 30px 26px 26px;
  border-radius: 8px 12px 9px 11px;
  border: 1.5px solid var(--linen);
  position: relative;
  transition: transform 0.25s var(--ease-soft);
}

.t-card .pin {
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--coral);
  border: 2px solid var(--parchment);
  box-shadow: 0 2px 3px rgba(0, 0, 0, 0.18);
}
.t-card .pin::after {
  content: "";
  position: absolute;
  inset: 4px;
  background: rgba(245, 237, 218, 0.5);
  border-radius: 50%;
}

.t-card .qmark {
  font-family: var(--font-h);
  font-size: 70px;
  font-weight: 900;
  line-height: 0.7;
  color: var(--mustard);
  margin-bottom: 4px;
  display: block;
}

.t-card blockquote {
  font-family: var(--font-h);
  font-style: italic;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.4;
  color: var(--ink);
  margin-bottom: 16px;
}
.t-card cite {
  font-family: var(--font-a);
  font-size: 14px;
  color: rgba(44, 33, 24, 0.7);
  font-style: normal;
}

/* ============================================================
   FOOTER
   ============================================================ */
.site-footer {
  background: var(--plum);
  color: var(--parchment);
  padding: 56px 0 32px;
  position: relative;
}
.footer-inner {
  max-width: 1240px;
  margin: 0 auto;
  padding: 0 32px;
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 40px;
}

.footer-brand h3 {
  font-family: var(--font-h);
  color: var(--parchment);
  font-size: 24px;
  margin-bottom: 8px;
}
.footer-brand p {
  font-family: var(--font-a);
  font-size: 18px;
  color: var(--mustard);
}
.footer-col h4 {
  font-family: var(--font-h);
  font-size: 14px;
  color: var(--mustard);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 12px;
  font-weight: 700;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 8px; }
.footer-col a {
  font-size: 15px;
  color: rgba(245, 237, 218, 0.78);
  transition: color 0.18s;
}
.footer-col a:hover { color: var(--coral); }

.footer-meta {
  max-width: 1240px;
  margin: 36px auto 0;
  padding: 24px 32px 0;
  border-top: 1px dashed rgba(245, 237, 218, 0.18);
  font-family: var(--font-a);
  font-size: 14px;
  color: rgba(245, 237, 218, 0.6);
  text-align: center;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 980px) {
  .nav-inner { padding: 14px 22px; }
  .nav-links { gap: 18px; }
  .nav-cta { display: none; }

  .hero-inner { grid-template-columns: 1fr; padding: 16px 28px; gap: 30px; }
  .hero-illustration { height: 320px; order: -1; }

  .story-grid { grid-template-columns: 1fr; gap: 40px; }
  .pullquote { position: static; }
  .pullquote .qmark { font-size: 110px; }

  .dark-story .section-wrap { grid-template-columns: 1fr; gap: 30px; }
  .smoke-wisp { width: 80px; right: 24px; }

  .feature-grid { grid-template-columns: repeat(2, 1fr); }
  .feature-card:nth-child(2),
  .feature-card:nth-child(5) { margin-top: 0; }

  .headliners-grid { grid-template-columns: 1fr; gap: 22px; }
  .headliner-card:nth-child(2),
  .headliner-card:nth-child(3) { margin-top: 0; }

  .supporting-grid { grid-template-columns: 1fr; }
  .supporting-grid .col-right { margin-top: 0; }

  .map-header .annotation { display: none; }
  .compass-rose { width: 110px; bottom: -60px; right: -20px; }

  .locations-grid { grid-template-columns: 1fr; }

  .pricing-grid { grid-template-columns: 1fr; }
  .pricing-wristband {
    position: relative;
    right: auto;
    top: auto;
    width: 88%;
    margin: 0 auto 30px;
    display: block;
  }

  .testimonials-grid { grid-template-columns: 1fr; }
  .testimonials-grid .t-card:nth-child(2),
  .testimonials-grid .t-card:nth-child(3) { margin-top: 0; }

  .footer-inner { grid-template-columns: 1fr; gap: 24px; }

  .section-wrap { padding: 0 22px; }
}

@media (max-width: 600px) {
  .nav-links { gap: 14px; font-size: 14px; }
  .nav-links a { font-size: 14px; }
  .brand { font-size: 18px; }
  .hero { padding: 50px 0 30px; }
  .hero-frame { inset: 12px; }
  .hero-h1 { font-size: clamp(40px, 9vw, 60px); }
  .hero-illustration { height: 240px; }
  .hero-ctas .btn { width: 100%; }

  .cta-panel { padding: 80px 22px; }

  .page-header { padding: 80px 0 60px; }

  .marquee-track { gap: 50px; }
  .stat-num { font-size: 52px; }

  .ghost-text { font-size: 60px; }

  .testimonials-grid .t-card { margin-top: 0 !important; }
}
